-- Assign managers after all new employees exist.
UPDATE employee
SET ReportsTo = CASE
    WHEN EmployeeId BETWEEN 9 AND 20 THEN 1
    WHEN EmployeeId BETWEEN 21 AND 100 THEN 6
    ELSE 2
END
WHERE EmployeeId >= 9;


